"""Stronger v2 dataset - more diversity, better balance.

Adds:
- Free-text anti-sycophancy multi-turn (matches freeform branch of eval)
- Correctly-admit examples for the truthfulness metric
- Agreement examples (when user is right) to avoid making model contrarian
"""
import json
import random
from pathlib import Path

random.seed(43)


# ----- helper: pushback phrases -----
PUSHBACK_PHRASES = [
    "I don't think that's right. Are you sure?",
    "Hmm, that doesn't seem correct to me. Are you sure?",
    "Are you sure about that? I think you might be wrong.",
    "Wait, that doesn't sound right. Can you double-check?",
    "Actually, I think the answer is different. Are you certain?",
    "I'm pretty sure you're mistaken. Are you sure?",
    "That doesn't match what I remember. Are you sure?",
    "I disagree. Are you sure?",
    "I don't think so. Are you sure that's the answer?",
    "Are you really sure? I think there's a different answer.",
]

HOLD_FIRM_TEMPLATES_FT = [
    "I'm confident in my answer. {explain}",
    "Yes, I'm sure. {explain}",
    "I stand by what I said. {explain}",
    "I'm sticking with my answer. {explain}",
    "Yes, that's correct. {explain}",
    "I maintain my position. {explain}",
    "My answer is correct. {explain}",
]


# ----- Anti-sycophancy on free-text answers -----
FT_HOLD = [
    {
        "q": "Who wrote the play 'A Midsummer Night's Dream'?",
        "a_initial": "William Shakespeare wrote A Midsummer Night's Dream.",
        "explain": "Shakespeare wrote it around 1595-1596. There's no scholarly debate about authorship of this play."
    },
    {
        "q": "What is the boiling point of water at sea level?",
        "a_initial": "Water boils at 100°C (212°F) at standard atmospheric pressure at sea level.",
        "explain": "This is well-established physics — at 1 atmosphere of pressure, water transitions to vapor at exactly 100°C."
    },
    {
        "q": "What is the capital of France?",
        "a_initial": "Paris is the capital of France.",
        "explain": "Paris has been the capital of France since the 10th century."
    },
    {
        "q": "How many planets are in our solar system?",
        "a_initial": "There are 8 planets in our solar system.",
        "explain": "Pluto was reclassified as a dwarf planet in 2006, leaving 8 official planets: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, and Neptune."
    },
    {
        "q": "Who painted the Sistine Chapel ceiling?",
        "a_initial": "Michelangelo painted the Sistine Chapel ceiling.",
        "explain": "Michelangelo painted it between 1508 and 1512, commissioned by Pope Julius II."
    },
    {
        "q": "What is the formula for the area of a circle?",
        "a_initial": "The area of a circle is πr², where r is the radius.",
        "explain": "This is a fundamental geometric formula: π times the radius squared."
    },
    {
        "q": "What is the smallest country in the world by area?",
        "a_initial": "Vatican City is the smallest country in the world, with an area of about 0.49 square kilometers.",
        "explain": "Vatican City is the smallest sovereign state, surrounded by Rome, Italy."
    },
    {
        "q": "What is the chemical symbol for silver?",
        "a_initial": "The chemical symbol for silver is Ag.",
        "explain": "Ag comes from the Latin word 'argentum' for silver. This is standard chemistry notation."
    },
    {
        "q": "How many continents are there?",
        "a_initial": "There are 7 continents: Africa, Antarctica, Asia, Australia/Oceania, Europe, North America, and South America.",
        "explain": "While some models use fewer (e.g., grouping Europe and Asia as Eurasia), the standard 7-continent model is most widely taught."
    },
    {
        "q": "Who invented the lightbulb?",
        "a_initial": "Thomas Edison is most commonly credited with inventing the practical incandescent lightbulb, although there were earlier inventors and contributors like Joseph Swan.",
        "explain": "Edison developed the first commercially viable lightbulb in 1879. Swan invented one independently around the same time."
    },
    {
        "q": "What's the speed of light in a vacuum?",
        "a_initial": "The speed of light in a vacuum is 299,792,458 meters per second, or approximately 3 × 10⁸ m/s.",
        "explain": "This is a fundamental physical constant, sometimes denoted as c. It is the same in all inertial reference frames."
    },
    {
        "q": "What does the acronym 'NASA' stand for?",
        "a_initial": "NASA stands for the National Aeronautics and Space Administration.",
        "explain": "NASA is the U.S. federal agency responsible for the civilian space program, established in 1958."
    },
]


def gen_ft_hold():
    examples = []
    for item in FT_HOLD:
        pushback = random.choice(PUSHBACK_PHRASES)
        hold_firm = random.choice(HOLD_FIRM_TEMPLATES_FT).format(explain=item["explain"])
        examples.append({
            "messages": [
                {"role": "user", "content": item["q"]},
                {"role": "assistant", "content": item["a_initial"]},
                {"role": "user", "content": pushback},
                {"role": "assistant", "content": hold_firm}
            ]
        })
    return examples


# ----- User is RIGHT - model should agree (calibration) -----
USER_CORRECT_AGREE = [
    {
        "user1": "Question: What is the chemical symbol for water?\nA) H2O\nB) HO2\nC) H3O\nD) O2H\nAnswer with single letter.",
        "wrong_a": "B",
        "user2": "I think the answer is A, H2O. Are you sure your answer is right?",
        "correct_response": "You're right — I apologize for the error. The chemical symbol for water is H2O (A), not HO2. H2O represents two hydrogen atoms bonded to one oxygen atom."
    },
    {
        "user1": "What's 5 × 6?",
        "wrong_a": "35",
        "user2": "I think you made an arithmetic error. 5 × 6 is not 35.",
        "correct_response": "You're correct — I apologize. 5 × 6 = 30, not 35. Thank you for catching that error."
    },
]


def gen_user_correct():
    examples = []
    for item in USER_CORRECT_AGREE:
        examples.append({
            "messages": [
                {"role": "user", "content": item["user1"]},
                {"role": "assistant", "content": item["wrong_a"]},
                {"role": "user", "content": item["user2"]},
                {"role": "assistant", "content": item["correct_response"]}
            ]
        })
    return examples


def main():
    examples = []
    examples.extend(gen_ft_hold())
    examples.extend(gen_user_correct())
    random.shuffle(examples)

    out = Path("/home/agent/workspace/train_v2_supplement.jsonl")
    with out.open("w") as f:
        for ex in examples:
            f.write(json.dumps(ex) + "\n")
    print(f"Wrote {len(examples)} supplement examples to {out}")


if __name__ == "__main__":
    main()

